  ar_t_tower:      ['Reaction', 'Реакция', 'Reflejos', '反应', 'Réflexes', 'Reaktion', '反射神経', '반응', 'Refleks'],
  ar_t_g2048:      ['Puzzle', 'Головоломка', 'Rompecabezas', '益智', 'Puzzle', 'Puzzle', 'パズル', '퍼즐', 'Teka-teki'],
